const IRON_PILLAR_INFO={id:"iron-pillar",title:"The Iron Pillar of Delhi",originRegion:"Mehrauli, Delhi, India",eraOrigin:"c. 4th–5th Century CE (Gupta Period)",quickStats:[{label:"Location",value:"Qutb Complex, Mehrauli, Delhi",icon:"📍"},{label:"Height",value:"~7.2 meters (23.6 ft)",icon:"📏"},{label:"Weight",value:"~6 tonnes",icon:"⚖️"},{label:"Age",value:"~1,600+ years, virtually rust-free",icon:"🕰️"},{label:"Key Element",value:"High Phosphorus, Low Sulfur Iron",icon:"🧪"},{label:"Protective Layer",value:"Misawite (Iron Hydrogen Phosphate Hydrate)",icon:"🛡️"}]},HISTORY_TEXT={title:"A Gupta-Era Monument That Outlasted Empires",paragraphs:["Standing in the Qutb Complex in Mehrauli, Delhi, the Iron Pillar is a single, solid shaft of wrought iron roughly 7.2 meters tall and weighing about six tonnes. A Sanskrit inscription on the pillar credits it to a king referred to as 'Chandra', widely identified by historians with the Gupta emperor Chandragupta II, dating the pillar to around the 4th to 5th century CE.","The pillar is believed to have originally served as a flagstaff, likely topped with an image of Garuda, and may have stood elsewhere before being relocated to its current site in Delhi, possibly during the reign of the Tomara dynasty in the 11th century CE.","What has fascinated metallurgists and engineers for over a century is not just its age or craftsmanship, but its condition: after more than 1,600 years exposed to Delhi's weather, the pillar shows only minor surface corrosion, with no significant structural rusting — an extraordinary feat for a large iron object of its age, especially one produced without any of the alloying techniques used in modern stainless steel.","The pillar has been studied extensively since the 20th century, with detailed metallurgical analysis in the late 1990s and early 2000s finally providing a widely accepted scientific explanation for its resistance to rust."]},COMPOSITION=[{label:"Iron Content",value:"~99.7% (wrought iron, produced by direct reduction)"},{label:"Phosphorus",value:"Unusually high, around 0.25% by weight"},{label:"Sulfur & Manganese",value:"Extremely low, unlike most iron of the period or today"},{label:"Carbon",value:"Very low, consistent with wrought iron rather than cast iron or steel"},{label:"Production Method",value:"Solid-state 'bloomery' reduction, iron never fully melted"}],CORROSION_STAGES=[{year:0,title:"Freshly Forged",ordinaryDescription:"Both bars begin as bare, unprotected iron with identical exposure to air and moisture.",pillarDescription:"The pillar's unusually high phosphorus content is already present, setting the stage for a very different reaction to weathering."},{year:50,title:"Early Weathering",ordinaryDescription:"Ordinary iron begins forming loose, flaky red rust (iron oxide) that offers no real protection and continues eating into the metal.",pillarDescription:"Phosphorus in the iron reacts with moisture and oxygen to begin forming a thin, adherent layer of iron hydrogen phosphate hydrate — later termed 'misawite' by researchers."},{year:300,title:"Layer Formation",ordinaryDescription:"Rust continues to flake off and re-form in cycles, progressively thinning the iron and weakening its structure.",pillarDescription:"The misawite layer thickens and bonds tightly to the metal surface, acting as a passive barrier that slows further oxygen and moisture penetration dramatically."},{year:1600,title:"Present Day",ordinaryDescription:"Unprotected iron of this age exposed to the elements would typically be almost entirely consumed by rust or structurally destroyed.",pillarDescription:"The pillar retains its structural integrity, protected by a stable, self-limiting phosphate layer just fractions of a millimeter thick — a natural passivation modern engineers still study."}],APPLICATIONS=[{title:"Weathering (Corten) Steel",description:"Modern weathering steels are engineered to form a stable, adherent oxide/phosphate layer that halts further corrosion — a principle directly echoing the Iron Pillar's chemistry."},{title:"Corrosion-Resistant Alloy Design",description:"Metallurgists studying the pillar's phosphorus-rich, low-sulfur composition have informed research into passivation layers for long-life infrastructure steel."},{title:"Heritage Conservation Science",description:"The pillar is a reference case in conservation metallurgy for understanding how ancient processing methods can produce unexpectedly durable materials."},{title:"Infrastructure Longevity Studies",description:"Insights from the pillar inform the design of bridges, pipelines, and structures meant to resist corrosion for a century or more with minimal maintenance."}],REFERENCES=[{text:"Balasubramaniam, R. — 'Delhi Iron Pillar: New Insights' (Indian Institute of Technology Kanpur / Aryan Books).",link:"#"},{text:"Balasubramaniam, R. — 'On the Corrosion Resistance of the Delhi Iron Pillar', Corrosion Science journal.",link:"#"},{text:"Archaeological Survey of India — Qutb Complex conservation records.",link:"#"},{text:"National Metallurgical Laboratory, India — Iron Pillar composition studies.",link:"#"}];